/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: slot, key, mbid, entry, manifestOf, draftWith, handle, lead, guest, approval
 *   Constants: importId
 * Tests
 *   - a track agrees with the Album only as exactly its primary entries: same artists in order, by ID when both carry one, with the byline phrases between them
 *   - the plan lists differing tracks only, shares an Album entry's identity by ID before name, groups track-only identities by key and keeps their handles stable
 *   - a track whose entries would pass the track-only identity bound, or credit one artist twice, publishes with the Album's primaries
 *   - identity entries add one synthetic featured entry per track-only identity a track not excluded credits, and decisions bound to them are kept
 *   - the draft cap never counts track Artist entries, a field save never names them, and a track holding them lists their path
 *   - each file takes its positionally paired release track's own entries when the counts agree; the release credit marker is the release's credit
 *   - a selected track's Credits follow its entries in order with their roles, keeping a phrase only before another entry, while other tracks keep the Album's primaries
 *   - format 4 is the format-3 shape with at most 20 frozen track-only identities and 1 to 100 track lists of 1 to 20 entries; anything else is unknown
 *   - the editor view never carries track entries, the server view keeps a strictly readable list, and a format-4 published view lists track-only Artists after the Album's
 *   - the summary of a new Album lists only differing tracks with each entry's identity, the track-only identities and the paired tracks taking the Album's Artists
 *   - preselections over the identity draft reuse a track-only Artist by exact ID, create one without candidates, and leave a name candidate to an explicit choice
 *   - Luna's input never carries a track's Artist entries
 * @end-catalog */

/**
 * Track Artist entries of an import that publishes a new Album, without a database: agreement with the Album's primary entries, the
 * plan of differing tracks and track-only identities, decisions bound to those identities, the positional assignment, the draft cap,
 * the Credits a selected track publishes, the format-4 approval shape and views, the summary keys, preselections over the identity
 * draft and Luna's input. All names and identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { ImportCandidatesResponse, ImportManifest } from '../../src/administration/import/adminImportContract';
import {
    DRAFT_V2_LIMITS, derivedEntryKey, importEntryIdentityKey, importIdentityDraft, importIdentityEntries, importSameArtist, importTrackAgrees, importTrackArtistPlan, importTrackEntries,
    retainBoundDecisions, type ImportArtistEntry, type ImportDecisionV2, type ImportDraftV2
} from '../../src/administration/import/adminImportDraft';
import { draftWithinSizeLimit, draftV2Paths, parseDraftPath } from '../../src/administration/import/adminImportValueState';
import { importDraftV2View, importPublishedV2View } from '../../src/administration/import/adminImportDraftCompat';
import { importPublicationFormat, type ImportPublication } from '../../src/administration/import/adminImportMediaTypes';
import { importNewAlbumTrackCredits, importTrackEntryCredits } from '../../src/administration/import/adminImportCatalogCommit';
import { importIdentityPreselections } from '../../src/administration/import/adminImportIdentity';
import { importIdentityAnswers, importSummaryView } from '../../src/administration/import/adminImportSummary';
import { lunaBaseline } from '../../src/administration/import/adminImportLuna';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { lookupTrackArtistAssignment, lookupTrackAssignment } from '../../src/administration/lookup/lookupRanking';
import type { MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';

const importId = '0000000000000000000000d7';
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const key = (index: number) => `0000000c-0000-4000-8000-${String(index).padStart(12, '0')}`;
const mbid = (index: number) => `0000000b-0000-4000-8000-${String(index).padStart(12, '0')}`;
const entry = (index: number, name: string, role: ImportArtistEntry['role'] = 'primary', joinPhrase: string | null = null, musicBrainzId: string | null = null): ImportArtistEntry =>
    ({ key: key(index), name, role, joinPhrase, musicBrainzId });
const manifestOf = (count: number): ImportManifest => ({ rootLabel: 'Synthetic Folder',
    files: Array.from({ length: count }, (_unused, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 })) });
/** A draft whose Album credits Lead (with an ID) and whose tracks hold the given entries (undefined: none). */
const draftWith = (lists: (ImportArtistEntry[] | undefined)[], album: ImportArtistEntry[] = [entry(1, 'Synthetic Lead', 'primary', null, mbid(1))]): ImportDraftV2 => ({
    album: { title: 'Synthetic Album', artists: album, label: null, releaseDate: null, visibility: 'public' },
    tracks: lists.map((artists, index) => ({ slotId: slot(index), title: `Song ${index + 1}`, discNumber: 1, trackNumber: index + 1, ...(artists ? { artists } : {}) }))
});
const handle = (identity: string) => derivedEntryKey({ importTrackIdentity: identity });
const lead = (index: number) => entry(100 + index, 'Synthetic Lead', 'primary', ' feat. ', mbid(1));
const guest = (index: number, name = 'Synthetic Guest', id: string | null = mbid(3)) => entry(200 + index, name, 'featured', null, id);

test('a track agrees with the Album only as exactly its primary entries: same artists in order, by ID when both carry one, with the byline phrases between them', () => {
    const album = [entry(1, 'Synthetic Lead', 'primary', ' & ', mbid(1)), entry(2, 'Synthetic Second', 'primary', ', ', mbid(2)), entry(3, 'Synthetic Guest', 'featured', null, mbid(3))];
    const same = [entry(11, 'synthetic lead', 'primary', ' & ', mbid(1)), entry(12, 'Second Spelling', 'primary', ' feat. ', mbid(2))];
    // Same IDs agree whatever the spelling, and the last entry's phrase is ignored.
    assert.equal(importTrackAgrees(same, album), true);
    // Without an ID on either side the names decide; two different IDs never agree, even under one name.
    assert.equal(importTrackAgrees([entry(11, 'SYNTHETIC LEAD', 'primary', ' & '), entry(12, 'Synthetic Second')], album), true);
    assert.equal(importTrackAgrees([entry(11, 'Synthetic Lead', 'primary', ' & ', mbid(9)), same[1]], album), false);
    // A featured entry, a missing or an extra primary, or another phrase between entries differs; a missing phrase reads as ', '.
    assert.equal(importTrackAgrees([same[0], { ...same[1], role: 'featured' }], album), false);
    assert.equal(importTrackAgrees([same[0]], album), false);
    assert.equal(importTrackAgrees([...same, entry(13, 'Synthetic Guest', 'primary', null, mbid(3))], album), false);
    assert.equal(importTrackAgrees([{ ...same[0], joinPhrase: ' and ' }, same[1]], album), false);
    assert.equal(importTrackAgrees([entry(11, 'A', 'primary', null), entry(12, 'B')], [entry(1, 'A', 'primary', ', '), entry(2, 'B')]), true);
    assert.deepEqual([importSameArtist(entry(1, 'A', 'primary', null, mbid(1)), entry(2, 'B', 'primary', null, mbid(1))), importSameArtist(entry(1, 'A'), entry(2, 'a', 'primary', null, mbid(1)))], [true, true]);
    assert.deepEqual([importEntryIdentityKey(entry(1, 'Ä', 'primary', null, mbid(4))), importEntryIdentityKey(entry(1, 'Ä'))], [`id:${mbid(4)}`, 'name:ä']);
});

test('the plan lists differing tracks only, shares an Album entry\'s identity by ID before name, groups track-only identities by key and keeps their handles stable', () => {
    const featuring = [lead(1), guest(1)];
    const draft = draftWith([[entry(10, 'Synthetic Lead', 'primary', null, mbid(1))], featuring, [lead(3), guest(3, 'Guest Spelling')], [entry(40, 'synthetic lead', 'primary', ' & '), guest(4, 'Other Guest', null)]]);
    const plan = importTrackArtistPlan(draft);
    // The agreeing first track is left out; the same guest ID on two tracks is one identity, a name-only guest another.
    assert.deepEqual(plan.differing.map(track => track.slotId), [slot(1), slot(2), slot(3)]);
    assert.deepEqual(plan.differing[0].identities, [key(1), handle(`id:${mbid(3)}`)]);
    assert.deepEqual(plan.differing[2].identities, [key(1), handle('name:other guest')]);
    assert.deepEqual(plan.identities, [{ key: handle(`id:${mbid(3)}`), name: 'Synthetic Guest', musicBrainzId: mbid(3), slotIds: [slot(1), slot(2)] },
        { key: handle('name:other guest'), name: 'Other Guest', musicBrainzId: null, slotIds: [slot(3)] }]);
    assert.deepEqual(plan.overBound, []);
    // An entry with the ID of a featured Album entry shares that entry, even under another name.
    const shared = importTrackArtistPlan(draftWith([featuring], [entry(1, 'Synthetic Lead', 'primary', null, mbid(1)), entry(2, 'Album Guest', 'featured', null, mbid(3))]));
    assert.deepEqual([shared.differing[0].identities, shared.identities], [[key(1), key(2)], []]);
    // The handles do not depend on the draft around them.
    assert.equal(importTrackArtistPlan(draftWith([undefined, undefined, featuring])).identities[0].key, plan.identities[0].key);
    // Malformed or primary-less stored lists read as none.
    for (const raw of ['x', [], [{ key: 1, name: 'A', role: 'primary' }], [guest(1)], Array.from({ length: 21 }, (_unused, index) => entry(index, `A${index}`))]) {
        assert.equal(importTrackEntries({ artists: raw }), null);
        assert.deepEqual(importTrackArtistPlan(draftWith([raw as ImportArtistEntry[]])).differing, []);
    }
});

test('a track whose entries would pass the track-only identity bound, or credit one artist twice, publishes with the Album\'s primaries', () => {
    const lists = Array.from({ length: 22 }, (_unused, index) => [lead(index), guest(index, `Guest ${index}`, mbid(300 + index))]);
    const plan = importTrackArtistPlan(draftWith(lists));
    assert.equal(plan.identities.length, DRAFT_V2_LIMITS.trackIdentities);
    assert.deepEqual(plan.overBound, [slot(20), slot(21)]);
    // Two entries of one list resolving to the Album's Lead (one by ID, one by name) are the same artist twice.
    const twice = importTrackArtistPlan(draftWith([[entry(10, 'Track Name', 'primary', ' & ', mbid(1)), entry(11, 'Synthetic Lead', 'primary')]]));
    assert.deepEqual([twice.differing, twice.overBound], [[], [slot(0)]]);
});

test('identity entries add one synthetic featured entry per track-only identity a track not excluded credits, and decisions bound to them are kept', () => {
    const draft = draftWith([[lead(0), guest(0)], [lead(1), guest(1, 'Other Guest', mbid(4))]]);
    const identity = (id: number) => handle(`id:${mbid(id)}`);
    assert.deepEqual(importIdentityEntries(draft).map(item => [item.key, item.name, item.role, item.musicBrainzId]),
        [[key(1), 'Synthetic Lead', 'primary', mbid(1)], [identity(3), 'Synthetic Guest', 'featured', mbid(3)], [identity(4), 'Other Guest', 'featured', mbid(4)]]);
    assert.deepEqual(importIdentityEntries(draft, new Set([slot(0)])).map(item => item.key), [key(1), identity(4)]);
    assert.deepEqual(importIdentityDraft(draft, new Set([slot(0), slot(1)])).album.artists, draft.album.artists);
    const decision = (entryKey: string, boundName: string, boundMusicBrainzId: string | null) =>
        ({ scope: 'artist', slotId: null, entryKey, boundName, boundMusicBrainzId, action: 'create-distinct', candidateId: null, candidateRevision: null }) as ImportDecisionV2;
    const decisions = [decision(identity(3), 'Synthetic Guest', mbid(3)), decision(identity(4), 'Other Guest', mbid(4))];
    assert.deepEqual(retainBoundDecisions(decisions, draft), decisions);
    // Once the Album credits that guest (or no track credits it), its track-only decision is dropped.
    const credited = draftWith(draft.tracks.map(track => track.artists), [entry(1, 'Synthetic Lead', 'primary', null, mbid(1)), entry(2, 'Synthetic Guest', 'featured', null, mbid(3))]);
    assert.deepEqual(retainBoundDecisions(decisions, credited), [decisions[1]]);
    assert.deepEqual(retainBoundDecisions(decisions, draftWith([undefined, undefined])), []);
});

test('the draft cap never counts track Artist entries, a field save never names them, and a track holding them lists their path', () => {
    const before = draftWith([undefined]), after = draftWith([Array.from({ length: 20 }, (_unused, index) => entry(index, `${'N'.repeat(190)} ${index}`, 'primary', null, mbid(index)))]);
    after.album.title = 'T'.repeat(300);
    for (let index = 0; index < 120; index++) after.tracks.push({ slotId: `x-${index}`, title: 'T'.repeat(300), discNumber: null, trackNumber: null });
    assert.equal(draftWithinSizeLimit(before, draftWith([after.tracks[0].artists])), true);
    assert.throws(() => parseDraftPath(`tracks.${slot(0)}.artists`, manifestOf(1)));
    assert.equal(parseDraftPath(`tracks.${slot(0)}.artists`, manifestOf(1), { reviewPaths: true }), `tracks.${slot(0)}.artists`);
    assert.deepEqual(draftV2Paths(draftWith([[lead(0)], undefined])).filter(path => path.endsWith('.artists')), ['album.artists', `tracks.${slot(0)}.artists`]);
    assert.equal(DRAFT_V2_LIMITS.decisions, 142);
});

test('each file takes its positionally paired release track\'s own entries when the counts agree; the release credit marker is the release\'s credit', () => {
    const credit = (name: string, id: number, joinPhrase = '') => ({ name, joinPhrase, artistId: mbid(id), artistName: name });
    const track = (position: number, artistCredit?: unknown) => ({ position, number: String(position), title: `Song ${position}`, lengthMs: 200_000, recordingId: mbid(900 + position), isrcs: [],
        ...(artistCredit === undefined ? {} : { artistCredit }) });
    const release = { releaseId: mbid(50), releaseGroupId: mbid(51), title: 'Synthetic Album', status: 'Official', artistCredit: [credit('Synthetic Lead', 1)], labels: [], barcode: null, barcodeText: null,
        country: null, date: null, primaryType: 'Album', secondaryTypes: [], trackCount: 3, groupFirstReleaseDate: null, frontArtwork: null,
        media: [{ position: 1, format: 'DVD-Video', tracks: [] }, { position: 2, format: 'CD', tracks: [track(1, 'release'), track(2, [credit('Synthetic Lead', 1, ' feat. '), credit('Synthetic Guest', 3)]), track(3, [credit('Various Artists', 0)])] },
            { position: 3, format: 'CD', tracks: [track(1)] }] } as unknown as MusicBrainzRelease;
    const files = [0, 1, 2, 3].map(index => ({ slotId: slot(index), order: index, discNumber: null, trackNumber: null, durationMs: null, durationPrecisionMs: 0, title: null, identifiers: {} })) as never;
    const assignment = lookupTrackArtistAssignment(release, files)!;
    assert.deepEqual(assignment.map(item => item.slotId), lookupTrackAssignment(release, files)!.map(item => item.slotId));
    assert.deepEqual(assignment[0].artists, { artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: mbid(1) }] });
    assert.deepEqual(assignment[1].artists, { artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: ' feat. ', musicBrainzId: mbid(1) }, { name: 'Synthetic Guest', role: 'featured', joinPhrase: null, musicBrainzId: mbid(3) }] });
    assert.deepEqual([assignment[2].artists, assignment[3].artists], [{ reason: 'placeholder' }, { reason: 'missing' }]);
    assert.equal(lookupTrackArtistAssignment(release, (files as unknown[]).slice(0, 3) as never), null);
});

test('a selected track\'s Credits follow its entries in order with their roles, keeping a phrase only before another entry, while other tracks keep the Album\'s primaries', () => {
    const artist = (index: number) => String(index).padStart(24, 'a');
    assert.deepEqual(importTrackEntryCredits([{ role: 'primary', joinPhrase: ' feat. ', artistId: artist(1) }, { role: 'featured', joinPhrase: ' & ', artistId: artist(2) }]), [
        { creditId: `import_primary_${artist(1)}`, subjectType: 'artist', subjectId: artist(1), role: 'primary', order: 0, joinPhrase: ' feat. ' },
        { creditId: `import_featured_${artist(2)}`, subjectType: 'artist', subjectId: artist(2), role: 'featured', order: 1 }]);
    const album = [{ creditId: `import_primary_${artist(1)}`, subjectType: 'artist' as const, subjectId: artist(1), role: 'primary' as const, order: 0, joinPhrase: ' feat. ' },
        { creditId: `import_featured_${artist(2)}`, subjectType: 'artist' as const, subjectId: artist(2), role: 'featured' as const, order: 1 }];
    assert.deepEqual(importNewAlbumTrackCredits(album as never), [{ creditId: `import_primary_${artist(1)}`, subjectType: 'artist', subjectId: artist(1), role: 'primary', order: 0 }]);
});

/** A format-3 approval shape with one frozen Album Artist, then format-4 fields. */
const approval = (extra: Partial<ImportPublication> & Record<string, unknown> = {}) => ({ schemaVersion: 4, snapshot: draftWith([undefined]), label: null,
    artists: [{ entryKey: key(1), artistId: 'a'.repeat(24), newArtist: true, candidateRevision: null }],
    trackIdentities: [{ entryKey: handle('name:g'), name: 'G', musicBrainzId: null, artistId: 'b'.repeat(24), newArtist: true, candidateRevision: null }],
    trackArtists: [{ slotId: slot(0), entries: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: ' feat. ', artistId: 'a'.repeat(24) }, { name: 'G', role: 'featured', joinPhrase: null, artistId: 'b'.repeat(24) }] }],
    ...extra });

test('format 4 is the format-3 shape with at most 20 frozen track-only identities and 1 to 100 track lists of 1 to 20 entries; anything else is unknown', () => {
    assert.equal(importPublicationFormat(approval()), 4);
    assert.equal(importPublicationFormat({ ...approval(), schemaVersion: 3 }), 3);
    assert.equal(importPublicationFormat(approval({ trackIdentities: [] })), 4);
    for (const extra of [{ trackIdentities: undefined }, { trackIdentities: Array.from({ length: 21 }, () => ({})) }, { trackArtists: [] }, { trackArtists: undefined },
        { trackArtists: Array.from({ length: 101 }, () => ({ slotId: slot(0), entries: [{}] })) }, { trackArtists: [{ slotId: 7, entries: [{}] }] }, { trackArtists: [{ slotId: slot(0), entries: [] }] },
        { schemaVersion: 5 }, { artists: [] }]) assert.equal(importPublicationFormat(approval(extra as never)), null, JSON.stringify(Object.keys(extra)));
});

test('the editor view never carries track entries, the server view keeps a strictly readable list, and a format-4 published view lists track-only Artists after the Album\'s', () => {
    const stored = draftWith([[lead(0), guest(0)], [{ key: 'bad', name: 'x' } as never]]);
    assert.ok(importDraftV2View(stored, manifestOf(2), importId).tracks.every(track => !('artists' in track)));
    const view = importDraftV2View(stored, manifestOf(2), importId, { trackArtists: true });
    assert.deepEqual([view.tracks[0].artists, 'artists' in view.tracks[1]], [[lead(0), guest(0)], false]);
    const publication = { ...approval(), state: 'complete', albumId: 'c'.repeat(24), artistId: 'a'.repeat(24), tracks: [{ id: 'd'.repeat(24) }] } as unknown as ImportPublication;
    assert.deepEqual(importPublishedV2View(publication)!.artistIds, ['a'.repeat(24), 'b'.repeat(24)]);
    assert.deepEqual(importPublishedV2View({ ...publication, schemaVersion: 3 })!.artistIds, ['a'.repeat(24)]);
});

test('the summary of a new Album lists only differing tracks with each entry\'s identity, the track-only identities and the paired tracks taking the Album\'s Artists', () => {
    const draft = draftWith([[entry(10, 'Synthetic Lead', 'primary', null, mbid(1))], [lead(1), guest(1)], undefined]);
    const release = { releaseId: mbid(50), title: 'Synthetic Album', artistCredit: [], labels: [], media: [{ position: 1, format: 'CD', tracks: [1, 2, 3].map(position => ({ position, title: `Song ${position}`, lengthMs: null })) }] };
    const doc = (decisions: unknown[] = [], applied: unknown = { choice: 'chosen', candidateKey: 'k', releaseId: mbid(50) }) => ({ purpose: 'import', lookup: {
        applied, candidates: [{ key: 'k', details: 'fetched', releaseId: mbid(50), release }] }, doc: { _id: new ObjectId(importId), draftVersion: 2, draft, draftOrigins: {}, manifest: manifestOf(3),
        media: { assets: [] }, decisions, suggestions: [], analysis: { state: 'idle', generation: 0 }, receipts: [] } as unknown as AdminImportDocument });
    const context = { now: new Date(), dailyAttemptsUsed: 0, lookupAvailable: true, identityAnswers: 0 };
    const { doc: project, lookup } = doc();
    const summary = importSummaryView(project, lookup as never, context);
    assert.deepEqual(summary.trackArtists, [{ slotId: slot(1), entries: [{ ...lead(1), identity: key(1) }, { ...guest(1), identity: handle(`id:${mbid(3)}`) }] }]);
    assert.deepEqual(summary.trackIdentities, [{ key: handle(`id:${mbid(3)}`), name: 'Synthetic Guest', musicBrainzId: mbid(3), slotIds: [slot(1)] }]);
    assert.deepEqual(summary.inheritsAlbum, [slot(2)]);
    // Without a paired applied candidate, after choosing none, or for a saved append, the keys are absent.
    assert.equal(importSummaryView(project, null, context).inheritsAlbum, undefined);
    assert.equal(importSummaryView(project, { ...lookup, applied: { choice: 'none', candidateKey: null, releaseId: null } } as never, context).inheritsAlbum, undefined);
    const append = doc([{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: 'e'.repeat(24), candidateRevision: 'f'.repeat(64) }]);
    assert.deepEqual(['trackArtists', 'trackIdentities', 'inheritsAlbum'].filter(name => name in importSummaryView(append.doc, append.lookup as never, context)), []);
    // An agreeing draft sends none of the keys.
    const agreeing = doc(); (agreeing.doc.draft as ImportDraftV2).tracks.forEach(track => { track.artists = [entry(10, 'Synthetic Lead', 'primary', null, mbid(1))]; });
    assert.deepEqual(['trackArtists', 'trackIdentities', 'inheritsAlbum'].filter(name => name in importSummaryView(agreeing.doc, agreeing.lookup as never, context)), []);
    // The summary's count of identity rows reads the saved draft alone: a track-only identity never holds its Publish.
    const decided = [{ scope: 'artist', slotId: null, entryKey: key(1), boundName: 'Synthetic Lead', boundMusicBrainzId: mbid(1), action: 'create-distinct', candidateId: null, candidateRevision: null },
        { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null },
        ...[0, 1, 2].map(index => ({ scope: 'track', slotId: slot(index), entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }))] as ImportDecisionV2[];
    assert.equal(importIdentityAnswers(draft, decided, []), 0);
});

test('preselections over the identity draft reuse a track-only Artist by exact ID, create one without candidates, and leave a name candidate to an explicit choice', () => {
    const draft = importIdentityDraft(draftWith([[lead(0), guest(0)], [lead(1), guest(1, 'Named Guest', null)], [lead(2), guest(2, 'New Guest', mbid(6))]]));
    const candidate = (id: string, label: string, extra: Record<string, unknown> = {}) => ({ kind: 'artist', id, label, revision: 'r', albumId: null, visibility: 'public', match: 'name', matchedSlotIds: [], ...extra });
    const candidates = { items: [candidate('1'.repeat(24), 'Holder', { match: 'musicBrainzId', musicBrainzId: mbid(3) }), candidate('2'.repeat(24), 'Named Guest')], memberMatchesComplete: true, unavailable: [] } as unknown as ImportCandidatesResponse;
    const preselected = importIdentityPreselections(draft, [], candidates).filter(decision => decision.scope === 'artist');
    const of = (name: string) => preselected.find(decision => decision.boundName === name);
    assert.deepEqual([of('Synthetic Guest')?.action, of('Synthetic Guest')?.candidateId], ['reuse', '1'.repeat(24)]);
    assert.equal(of('New Guest')?.action, 'create-distinct');
    assert.equal(of('Named Guest'), undefined);
    // An Album entry's explicit reuse of the record holding the guest's ID takes it, so the guest is not preselected onto it too.
    const taken = [{ scope: 'artist', slotId: null, entryKey: key(1), boundName: 'Synthetic Lead', boundMusicBrainzId: mbid(1), action: 'reuse', candidateId: '1'.repeat(24), candidateRevision: 'r' }] as ImportDecisionV2[];
    assert.equal(importIdentityPreselections(draft, taken, candidates).find(decision => decision.boundName === 'Synthetic Guest'), undefined);
});

test('Luna\'s input never carries a track\'s Artist entries', () => {
    const baseline = lunaBaseline(draftWith([[lead(0), guest(0)]]), [slot(0)], false);
    assert.ok(!JSON.stringify(baseline).includes('Synthetic Guest'));
    assert.deepEqual(Object.keys(baseline.tracks[0]).sort(), ['discNumber', 'slotId', 'title', 'trackNumber']);
});
